def test_cloud_events_scalar_top_level_roundtrip(sample):
    """不输出嵌套 extensions；causedby 标量映射，实际 JSON UTF-8 往返一致。"""
    schema = collection_event_schema().model_copy(update={"routable_attributes": ["attrscore"]})
    intent = sample.intent.model_copy(update={"routing": {"attrscore": 7}, "causedby": ["parent-a", "parent-b"]})
    record = EventRecord(**intent.model_dump(), emittedat="2026-11-04T07:01:00Z", traceparent="trace-probe")
    wire = event_to_wire(record, schema)
    assert wire["specversion"] == "1.0" and wire["attrscore"] == 7 and wire["causedby"] == "parent-a,parent-b"
    assert not {"routing", "content_kind", "extensions"} & set(wire)
    assert decode_cloud_event(encode_cloud_event(record, schema), schema) == record
    assert all(type(value) in {str, int, bool} for key, value in wire.items() if key != "data")
    null_optional = dict(wire, subjectseq=None, actorobo=None, expiresat=None, hops=None, attrscore=None)
    decoded = decode_cloud_event(canonicalize(null_optional), schema)
    assert decoded.routing == {} and decoded.hops == 0


@pytest.mark.parametrize("mutation", ["missing_spec", "null_spec", "wrong_spec", "comma_id", "compound_route", "unknown_route", "storage_field", "unknown_field", "duplicate_key", "binary", "bad_causedby", "too_many_parents"])
def test_wire_rejections_are_sanitized(sample, mutation):
    """格式损坏不回显原始响应，内部默认 specversion 不掩盖线格式必填字段。"""
    schema = collection_event_schema()
    wire = event_to_wire(finalized(sample), schema)
    if mutation == "missing_spec": wire.pop("specversion")
    elif mutation == "null_spec": wire["specversion"] = None
    elif mutation == "wrong_spec": wire["specversion"] = "1.1"
    elif mutation == "comma_id": wire["id"] = "bad,id"
    elif mutation == "compound_route": wire["attrunknown"] = {"private": "must-not-echo"}
    elif mutation == "unknown_route": wire["attrunknown"] = "must-not-echo"
    elif mutation == "storage_field": wire["routing"] = {}
    elif mutation == "unknown_field": wire["bad_field"] = "must-not-echo"
    elif mutation == "binary": wire["data_base64"] = "YmFk"
    elif mutation == "bad_causedby": wire["causedby"] = ["must-not-echo"]
    elif mutation == "too_many_parents": wire["causedby"] = ",".join("p"+str(i) for i in range(33))
    payload = b'{"id":"a","id":"must-not-echo"}' if mutation == "duplicate_key" else json.dumps(wire).encode()
    with pytest.raises(WireDecodeError) as error:
        decode_cloud_event(payload, schema)
    assert "must-not-echo" not in str(error.value)


def test_inline_limit_source_reference_and_causal_sequence(sample):
    """16 KiB 是严格上界；来源必须引用；uint64 保持字符串且仅 causal 可带。"""
    data = sample.intent.model_dump()
    data["data"] = {"x": "a"*16375}
    assert len(canonicalize(EventIntent(**data).data)) == 16383
    data["data"]["x"] += "a"
    with pytest.raises(ValueError):
        EventIntent(**data)
    data = sample.intent.model_dump()
    data["content_kind"] = "source_content"
    with pytest.raises(ValueError):
        EventIntent(**data)
    data.update(data=None, dataref="evd://sha256:" + "b"*64, datadigest="sha256:" + "c"*64)
    source = EventIntent(**data)
    schema = collection_event_schema().model_copy(update={"content_kind": "source_content", "ordering": "causal"})
    record = finalize_event(source, schema, emitted_at="2026-11-04T07:01:00Z", traceparent="trace-probe", subject_sequence="18446744073709551615", ordering="causal")
    assert decode_cloud_event(encode_cloud_event(record, schema), schema).subjectseq == "18446744073709551615"
    for sequence in ("0", "01", "18446744073709551616"):
        with pytest.raises(ValueError):
            EventRecord(**(record.model_dump() | {"subjectseq": sequence}))
    with pytest.raises(ValueError):
        encode_cloud_event(record.model_copy(update={"content_kind": "metadata"}), collection_event_schema())


